import type {PushInput} from "../types/push-input.js";
import {commonEvent,mapEvent,troopEvent,showPicture,imageAsset,callCommonEvent,commonEventRef,forceAction,actorRef,skillRef,showAnimation,animationRef} from "rpgmaker-event-dsl";
export const event=commonEvent({id:10,name:"Push workflow",trigger:"none",commands:[showPicture({pictureId:1,image:imageAsset({folder:"pictures",name:"PushPoster"}),origin:"upperLeft",position:{kind:"direct",x:0,y:0},scaleX:100,scaleY:100,opacity:255,blendMode:"normal"})]});
import {switchDefinition} from "rpgmaker-event-dsl";
export const gate=switchDefinition({id:1,name:"Recovery switch"});

before.publicTypes:
export const runtimeBaseline = {
  language: "typescript-strict",
  moduleSystem: "esm-nodenext",
  packageManager: "pnpm",
  runtime: "node-22-lts",
} as const;

export * from "./authoring/index.js";

export type RuntimeBaseline = typeof runtimeBaseline;

